`timescale 1ns/1ps
// Independent vectors are generated by check_srp_lag_ring.py. The DUT is
// exercised through MMIO for LUT/P and through the local IFFT transfer for R.
module tb_srp_lag_ring;
  parameter integer R_LEN=64, IDX_W=$clog2(R_LEN), FAST_SCAN=1;
  localparam integer NP=36, NG=1024, AW=16;
  reg clk=0; always #5 clk=~clk;
  reg rst_n=0, start=0, wr=0, rd=0;
  reg [6:0] addr=0;
  reg [31:0] wdata=0;
  wire [31:0] rdata;
  wire busy;
  reg transfer=0, r_we=0;
  reg [AW-1:0] r_addr=0;
  reg [15:0] r_data=0;
  wire signed [31:0] p_data;
  wire done;
  reg [IDX_W+3:0] lut_vectors[0:NP*NG-1];
  reg [15:0] r_vectors[0:NP*R_LEN-1];
  reg [31:0] golden[0:NG-1];
  reg [4095:0] lut_file, r_file, golden_file;
  integer i, pass, cycles, cycles0, total_checks=0;
  rv32_srp_regs #(.N_PAIR(NP),.N_GRID(NG),.R_LEN(R_LEN),
    .IDX_W(IDX_W),.FRAC_W(4),.ADDR_W(AW),.GRID_IDX_W(10),
    .FAST_SCAN(FAST_SCAN),.LOCAL_TRANSFER(1)) dut (
    .clk_i(clk),.rst_n_i(rst_n),.core_start_i(start),
    .core_wr_i(wr),.core_rd_i(rd),.core_addr_i(addr),
    .core_wdata_i(wdata),.core_rdata_o(rdata),
    .ps_wr_i(1'b0),.ps_rd_i(1'b0),.ps_addr_i(7'd0),
    .ps_wdata_i(32'd0),.ps_rdata_o(),.busy_o(busy),
    .transfer_enable_i(transfer),.transfer_r_we_i(r_we),
    .transfer_r_addr_i(r_addr),.transfer_r_data_i(r_data),
    .transfer_p_addr_i(10'd0),.transfer_p_data_o(p_data),
    .transfer_done_o(done));

  task write_reg(input [6:0] a,input [31:0] d);
    begin
      @(negedge clk); addr=a; wdata=d; wr=1;
      @(negedge clk); wr=0;
    end
  endtask

  always @(posedge clk) cycles<=cycles+1;
  initial begin
    cycles=0;
    if (!$value$plusargs("LUT=%s",lut_file) ||
        !$value$plusargs("R=%s",r_file) ||
        !$value$plusargs("GOLDEN=%s",golden_file))
      $fatal(1,"missing vectors");
    $readmemh(lut_file,lut_vectors);
    $readmemh(r_file,r_vectors);
    $readmemh(golden_file,golden);
    repeat(4) @(negedge clk); rst_n=1;
    write_reg(2,0);
    for(i=0;i<NP*NG;i=i+1) write_reg(3,lut_vectors[i]);
    @(negedge clk); addr=2; rd=1;
    #1; if(rdata!==0) $fatal(1,"LUT address did not wrap");
    @(negedge clk); rd=0;

    // Repeat the complete scan to prove pair zero clears the previous map.
    for(pass=0;pass<2;pass=pass+1) begin
      @(negedge clk); transfer=1;
      for(i=0;i<NP*R_LEN;i=i+1) begin
        @(negedge clk); r_we=1; r_addr=i; r_data=r_vectors[i];
      end
      @(negedge clk); r_we=0; transfer=0; start=1; cycles0=cycles;
      @(negedge clk); start=0;
      // Neither MMIO nor the IFFT transfer may mutate a running correlation.
      write_reg(2,(1<<AW));
      write_reg(3,32'h1234);
      @(negedge clk); addr=2; rd=1;
      #1; if(rdata!==(1<<AW)) $fatal(1,"rejected write advanced R address");
      @(negedge clk); addr=1;
      #1; if(!rdata[3]) $fatal(1,"busy write did not set WERR");
      @(negedge clk); rd=0;
      write_reg(0,10); // keep EN, clear WERR
      @(negedge clk); transfer=1; r_we=1; r_addr=0; r_data=16'h1234;
      @(negedge clk); transfer=0; r_we=0;
      while(!done && cycles-cycles0<200000) @(negedge clk);
      if(!done) $fatal(1,"scan timeout");
      if(FAST_SCAN && cycles-cycles0>NP*(NG+12)+4)
        $fatal(1,"fast scanner lost its pipelined throughput");
      if(FAST_SCAN==4 && cycles-cycles0>((NP+3)/4)*(NG+12)+4)
        $fatal(1,"four-pair scanner lost its pipelined throughput");
      $display("SCAN_CYCLES rlen=%0d idx=%0d fast=%0d pass=%0d cycles=%0d",
        R_LEN,IDX_W,FAST_SCAN,pass,cycles-cycles0);
      repeat(3) @(negedge clk);
      write_reg(2,(2<<AW));
      for(i=0;i<NG;i=i+1) begin
        // A synchronous BRAM read needs one idle cycle after address changes.
        @(negedge clk); addr=4; rd=1;
        #1;
        if(rdata!==golden[i])
          $fatal(1,"grid %0d got=%0d expected=%0d",i,$signed(rdata),$signed(golden[i]));
        total_checks=total_checks+1;
        @(negedge clk); rd=0;
      end
      @(negedge clk); addr=1; rd=1;
      #1; if(rdata[3]) $fatal(1,"unexpected MMIO WERR");
      @(negedge clk); rd=0;
    end
    $display("SRP_LAG_RING_PASS rlen=%0d idx=%0d fast=%0d scores=%0d",
      R_LEN,IDX_W,FAST_SCAN,total_checks);
    $finish;
  end
  initial begin #5000000; $fatal(1,"test timeout"); end
endmodule
